import * as React from 'react';
import {Dialog as D} from '@base-ui/react/dialog';
import {X} from 'lucide-react';
import {RadialInspector,type RadialInspectorProps} from './radial-inspector';
export interface RadialInspectorOverlayProps extends RadialInspectorProps {open:boolean;onOpenChange:(open:boolean)=>void;anchorPoint?:{x:number;y:number}|null}
export function RadialInspectorOverlay({open,onOpenChange,anchorPoint,size,displayMode='compact',...props}:RadialInspectorOverlayProps){const [viewport,setViewport]=React.useState({w:typeof window==='undefined'?1000:window.innerWidth,h:typeof window==='undefined'?900:window.innerHeight});React.useEffect(()=>{const resize=()=>setViewport({w:window.innerWidth,h:window.innerHeight});window.addEventListener('resize',resize);return()=>window.removeEventListener('resize',resize)},[]);const width=Math.max(200,Math.min(size??(displayMode==='compact'?460:700),viewport.w-24,viewport.h-177));const height=width+146;const x=Math.max(width/2+12,Math.min(anchorPoint?.x??viewport.w/2,viewport.w-width/2-12));const y=Math.max(height/2+12,Math.min(anchorPoint?.y??viewport.h/2,viewport.h-height/2-12));return <D.Root open={open} modal={false} onOpenChange={onOpenChange}><D.Portal><D.Popup className="nb-radial-popup" data-nodrag="1" style={{left:x,top:y,width,maxHeight:viewport.h-24}} onPointerDown={e=>e.stopPropagation()}><D.Title className="sr-only">{props.title||'Radial inspector'}</D.Title><D.Close className="nb-radial-popup-close" aria-label="Close radial inspector"><X size={14}/></D.Close><RadialInspector {...props} displayMode={displayMode} size={width}/></D.Popup></D.Portal></D.Root>}
